#pragma once

#include <stdbool.h>
#include <stdint.h>

/* On-board addressable RGB LED (WS2812 class, one wire, 800 kHz bit timing).
 *
 * The LED cannot be driven with plain gpio_set_level(): the protocol lives in the
 * pulse widths, so it is generated by an RMT channel instead and the pin is taken
 * out of the GPIO command's pool. Disabled when CONFIG_ESP_SDR_LED_PIN is -1. */

void burst_led_init(void);

/* True when this module owns the line (answered or rejected). */
bool burst_led_command(const char *line);

/* Sets the colour; returns false when no LED is configured or RMT is unavailable. */
bool burst_led_set(uint8_t r, uint8_t g, uint8_t b);

/* GPIO the LED sits on, or -1 when this board has none (excluded from GPIO control). */
int burst_led_owned_pin(void);
